    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl = 0, finl = 0;

    // init once, reset iv/key each time
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);

    // warmup
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(ctx, ct + outl, &finl);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    int reps = 8;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + outl, &finl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("reuse ctx %.5f s  GB/s %.2f\n", (t1-t0)/reps, (n / ((t1-t0)/reps)) / 1e9);

    // no aad
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + outl, &finl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("no aad %.5f s  GB/s %.2f\n", (t1-t0)/reps, (n / ((t1-t0)/reps)) / 1e9);

    // chunked 16k like openssl speed
    t0 = now();
    int chunk = 16384;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        size_t off = 0;
        while (off < n) {
            int len = chunk;
            if (off + len > n) len = (int)(n - off);
            EVP_EncryptUpdate(ctx, ct + off, &outl, pt + off, len);
            off += len;
        }
        EVP_EncryptFinal_ex(ctx, ct + n, &finl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("chunked 16k %.5f s  GB/s %.2f\n", (t1-t0)/reps, (n / ((t1-t0)/reps)) / 1e9);

    // one huge update but int max? 60MB fits in int
    printf("outl last %d\n", outl);
