}

void *worker_ctr(void *p) {
    arg *a = p;
    size_t blocks = N/16;
    size_t baseb = (blocks / a->nt) & ~(size_t)7;
    size_t start = a->id * baseb;
    size_t cnt = (a->id == a->nt-1) ? ((blocks - start) & ~(size_t)7) : baseb;
    ctr_xor8(pt + start*16, ct + start*16, cnt, ctr_at((uint32_t)(start + 2)));
    return NULL;
}
void *worker_ghash(void *p) {
    arg *a = p;
    size_t blocks = N/16;
    size_t baseb = blocks / a->nt;
    size_t start = a->id * baseb;
    size_t cnt = (a->id == a->nt-1) ? (blocks - start) : baseb;
    a->acc = ghash_pass(ct + start*16, cnt);
    return NULL;
}

