    memset(pt, 1, N);
    int reps = 3;
    for (int nt = 1; nt <= 6; nt++) {
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            pthread_t th[8]; arg args[8];
            for (int i = 0; i < nt; i++) { args[i].id=i; args[i].nt=nt; pthread_create(&th[i], NULL, worker_ctr, &args[i]); }
            for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        }
        double dt = (now()-t0)/reps;
        printf("ctr+xor nt %d  %.5f s  %.2f GB/s\n", nt, dt, (N/dt)/1e9);
    }
    for (int nt = 1; nt <= 4; nt++) {
        pthread_t th[8]; arg args[8];
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            for (int i = 0; i < nt; i++) { args[i].id=i; args[i].nt=nt; pthread_create(&th[i], NULL, worker_ghash, &args[i]); }
            for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
        }
        double dt = (now()-t0)/reps;
        sinkv = _mm_extract_epi32(args[0].acc, 0);
        printf("ghash-like nt %d  %.5f s  %.2f GB/s sink %d\n", nt, dt, (N/dt)/1e9, sinkv);
    }
    /* combined single-thread ctr then ghash */
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        ctr_xor8(pt, ct, N/16, ctr_at(2));
        __m128i y = ghash_pass(ct, N/16);
        sinkv ^= _mm_extract_epi32(y, 0);
    }
    double dt = (now()-t0)/reps;
    printf("single ctr+ghash %.5f s  %.2f GB/s\n", dt, (N/dt)/1e9);
    return 0;
}
